ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'art/ruta-native-painted-sprites-v2'
parser=argparse.ArgumentParser();parser.add_argument('--reference',default='public/assets/characters-v1/ruta-idle-pilot.png');parser.add_argument('--case',choices=['12','48'],default='48');args=parser.parse_args();N=int(args.case);P=BASE/('full48'if N==48 else'');O=BASE/'packing'/('full48'if N==48 else'');O.mkdir(parents=True,exist_ok=True)
ref=(ROOT/args.reference).resolve();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();rawpath=P/'painted-sheet-v1.png';rawhash=sha(rawpath);raw=Image.open(rawpath).convert('RGBA');pixels=np.array(raw);assert raw.size==(1295,1215);source=json.loads((P/'source-grid.json').read_text());assert len(source['rows'])==N
