COLS,ROWS=(8,6)if N==48 else(4,3);W,H=(162,200)if N==48 else(324,384);GRID_X,GRID_Y=(0,30)if N==48 else(0,32);PAD_W=COLS*W;PAD_H=max(raw.height,GRID_Y+ROWS*H);NW,NH=source['cellSize'];native_scale=NW/512;assert NH/640==native_scale
