grid={'origin':[GRID_X,GRID_Y],'columnPitch':W,'rowPitch':H,'columns':COLS,'rows':ROWS,'frameSize':[W,H],'reason':'one shared nonoverlapping grid contains all alpha>128 actor components; intentionally not raw dimensions divided into equal rows','notUniquePhysicalRegistration':True,'rightPaddingPixels':PAD_W-raw.width,'bottomPaddingPixels':PAD_H-raw.height,'rawUnassignedTopGutterPixels':GRID_Y}
padded=Image.new('RGBA',(PAD_W,PAD_H));padded.paste(raw,(0,0));assert padded.crop((0,0,*raw.size)).tobytes()==raw.tobytes();padded.save(O/'painted-fixed-grid.png')
