 queue=[(int(y),int(x))];seen[y,x]=True
 for yy,xx in queue:
  for dy,dx in [(0,1),(0,-1),(1,0),(-1,0)]:
   Y,X=yy+dy,xx+dx
   if 0<=Y<raw.height and 0<=X<raw.width and mask[Y,X]and not seen[Y,X]:seen[Y,X]=True;queue.append((Y,X))
 a=np.array(queue);components.append({'pixels':len(queue),'bbox':[int(a[:,1].min()),int(a[:,0].min()),int(a[:,1].max()+1),int(a[:,0].max()+1)],'centroid':[float(a[:,1].mean()),float(a[:,0].mean())]})
