def descriptor(im):
 a=np.array(im);yy,xx=np.where(a[:,:,3]>128);top=yy<yy.min()+.15*(yy.max()+1-yy.min());bottom=yy>yy.max()-.15*(yy.max()+1-yy.min());b=[int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)]
 points=np.array([[xx.mean(),yy.mean()],[xx[top].mean(),yy[top].mean()],[xx[bottom].mean(),yy[bottom].mean()],b[:2],b[2:]],dtype=float)
 return {'bbox':b,'centroid':points[0].tolist(),'crownBandCentroid':points[1].tolist(),'lowerBandCentroid':points[2].tolist(),'fitPoints':points.tolist(),'alphaThreshold':128,'crownAndLowerBandFraction':.15}
native=Image.new('RGBA',(COLS*NW,ROWS*NH));nativeInput=Image.open(P/native_sheet_name).convert('RGBA');rows=[];pairs=[];minimum=10000
for i,item in enumerate(source['rows']):
 assert item['cell']==i and item['nativePhaseIndex']==i*(48//N)
 x=GRID_X+(i%COLS)*W;y=GRID_Y+(i//COLS)*H;box=(x,y,x+W,y+H);cell=padded.crop(box);c=actors[i];b=c['bbox'];assert x<=b[0]and y<=b[1]and b[2]<=x+W and b[3]<=y+H,('BLOCKER actor crosses fixedcell',i,b,box)
 margin=min(b[0]-x,b[1]-y,x+W-b[2],y+H-b[3]);minimum=min(minimum,margin);file=O/'frames'/f'{i:02}.png';file.parent.mkdir(exist_ok=True);cell.save(file);assert Image.open(file).tobytes()==cell.tobytes()
 actual=ROOT/item['source'];assert sha(actual)==item['sourceSha256'];nim=Image.open(actual).convert('RGBA');assert nim.size==(512,640);nim=nim.resize((NW,NH),Image.Resampling.LANCZOS)if native_scale!=1 else nim;nx=(i%COLS)*NW;ny=(i//COLS)*NH;native.paste(nim,(nx,ny));assert nativeInput.crop((nx,ny,nx+NW,ny+NH)).tobytes()==nim.tobytes(),('sourceSheetMismatch',i)
 pd=descriptor(cell);nd=descriptor(nim);pairs.append((np.array(pd['fitPoints']),np.array(nd['fitPoints'])));rows.append({'cell':i,'nativePhaseIndex':item['nativePhaseIndex'],'paintedRect':[x,y,W,H],'nativeRect':[nx,ny,NW,NH],'frame':file.relative_to(O).as_posix(),'frameSha256':sha(file),'actorAlpha128Component':c,'actorMarginPx':margin,'nativePng':item['source'],'nativePngSha256':sha(actual),'paintedDescriptors':pd,'nativeDescriptors':nd})
native.save(O/f'native-matched{N}.png');assert native.tobytes()==nativeInput.tobytes()
paint=np.concatenate([p[0]for p in pairs]);nat=np.concatenate([p[1]for p in pairs]);pc=paint-paint.mean(axis=0);nc=nat-nat.mean(axis=0);scale=float((pc*nc).sum()/(pc*pc).sum());translation=nat.mean(axis=0)-scale*paint.mean(axis=0);errors=paint*scale+translation-nat
for i,row in enumerate(rows):row['globalDiagnosticProxyResidualNativePx']={k:{'delta':errors[i*5+j].tolist(),'length':float(np.linalg.norm(errors[i*5+j]))}for j,k in enumerate(['centroid','crownBand','lowerBand','bboxMin','bboxMax'])}
proxy={k:{'rmsNativePx':float(np.sqrt(np.mean(np.sum(errors[j::5]**2,axis=1)))),'maxNativePx':float(np.linalg.norm(errors[j::5],axis=1).max()),'maxSuccessiveDeltaMismatchNativePx':float(np.linalg.norm(np.roll(errors[j::5],-1,axis=0)-errors[j::5],axis=1).max())}for j,k in enumerate(['centroid','crownBand','lowerBand','bboxMin','bboxMax'])}
reference=O/('approved-reference'+ref.suffix);shutil.copyfile(ref,reference)
manifest={'schemaVersion':1,'status':f'MECHANICALLY-PACKABLE-{N}-POSE-STYLE-PILOT-NOT-ANIMATION-OR-ART-ACCEPTANCE','sourceCommit':'b06b455'if N==48 else'df4df44','nativeBlendSha256':source.get('nativeSourceSha256',json.loads((BASE/'source-grid.json').read_text())['nativeSourceSha256']),'raw':{'path':str(Path('../..')/('full48'if N==48 else'')/'painted-sheet-v1.png')if N==48 else'../painted-sheet-v1.png','sha256':rawhash,'size':list(raw.size)},'paintedAtlas':{'path':'painted-fixed-grid.png','size':list(padded.size),'frameSize':[W,H],'sha256':sha(O/'painted-fixed-grid.png'),'rawRgbaPreservedExactlyWithOnlyTransparentOuterPadding':True},'nativeAtlas':{'path':f'native-matched{N}.png','size':list(native.size),'frameSize':[NW,NH],'oneUniformScaleFromActualPngs':native_scale,'sha256':sha(O/f'native-matched{N}.png'),'matchesInputPoseSheetRgbaExactly':True},'reference':{'path':reference.name,'originalSource':str(ref.relative_to(ROOT)),'sha256':sha(ref)},'grid':grid,'frameCount':N,'cycleSeconds':source['nativeCycleSeconds'],'displayFramesPerSecond':N/source['nativeCycleSeconds'],'native48PhasesSampled':[r['nativePhaseIndex']for r in rows],'intermediatePosesGenerated':0,'frames':rows,'commonDiagnosticDisplayTransform':{'paintedCellToNativeCanvasUniformScale':scale,'translation':translation.tolist(),'fit':'ONE common scalar and XY translation over all selected shape descriptors (5perpose), not per-frame registration; metadata/display only, atlas RGBA untouched','rmsNativePx':float(np.sqrt(np.mean(np.sum(errors**2,axis=1)))),'maxNativePx':float(np.linalg.norm(errors,axis=1).max()),'perProxy':proxy,'uncertainty':'alpha128 shape descriptors, not semantic bones or physical support points; crown/lower15percent bands change membership, and artwork/proportions/heading differ. No exact joint correspondence or physical Root recovered.','poseCorrespondence':'intended row-major source phase mapping; hashes prove source inputs, not generated anatomical pose fidelity'},'noPerFrameOffsetScaleWarp':True,'productionEnabled':False}
native_delivery=json.loads((ROOT/'art/ruta-native-layered-walk48-v2/manifest.json').read_text())['cameraVariants']['base']['directions']['e'];native_anchor=np.array(native_delivery['footAnchor'])*(NW/256);native_height=native_delivery['nativeHeightPx']*(NW/256);manifest['nativeAtlas'].update({'nativeHeightPx':native_height,'footAnchor':native_anchor.tolist(),'nativeAssetMetadataSource':'art/ruta-native-layered-walk48-v2/manifest.json','nativeAssetMetadataSha256':sha(ROOT/'art/ruta-native-layered-walk48-v2/manifest.json')});manifest['assetLevelComparisonCalibration']={'nativeAnchor':native_anchor.tolist(),'nativeHeightPx':native_height,'paintedComparisonAnchor':((native_anchor-translation)/scale).tolist(),'paintedComparisonNativeHeightPx':native_height/scale,'scope':'ONE common diagnostic scalar/translation only; inferred drawn-origin metadata, NOT physical Root/joint/contact certification'}
(O/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
alpha=pixels[:,:,3];rgb=pixels[:,:,:3].astype(np.int16);red=(rgb[:,:,0]>rgb[:,:,1]+40)&(rgb[:,:,0]>rgb[:,:,2]+40);audit={'rawSha256Before':rawhash,'rawSha256After':sha(rawpath),'rawUnchanged':sha(rawpath)==rawhash,'alphaThresholdForMeasurementOnly':128,'largeActorComponents':actors,'smallComponentCount':len(components)-N,'smallComponentPixels':sum(c['pixels']for c in components if c['pixels']<=100),'minimumActorCellMarginPx':minimum,'alphaHistogram':{str(int(v)):int(n)for v,n in zip(*np.unique(alpha,return_counts=True))},'redDominantAlpha1Pixels':int(np.sum(red&(alpha==1))),'allAlpha1Pixels':int(np.sum(alpha==1)),'allRgbaIncludingLowAlphaNoisePreserved':True,'paddedAtlasOriginalRegionExact':padded.crop((0,0,*raw.size)).tobytes()==raw.tobytes(),'nativeSheetAndActualPosePngsExact':True,'gridStatus':'PASS mechanical containment only','blockers':[f'{N}selectedposes; frame count and raw hashes do not certify semantic pose continuity or smoothness.','Generated proportions/heading/foot poses differ; global proxy residuals remain and cannot be removed by fixed grid.','No semantic landmark registration, no-slip, runtime install or art acceptance claimed.','Raw low-alpha RGB noise preserved, not semantically cleaned.']};coverage=np.zeros(alpha.shape,dtype=bool);coverage[GRID_Y:min(GRID_Y+ROWS*H,raw.height),GRID_X:min(GRID_X+COLS*W,raw.width)]=True;audit['pixelsOutsidePackedRects']={'nonzeroAlpha':int(np.sum((alpha>0)&~coverage)),'alphaAbove128':int(np.sum((alpha>128)&~coverage)),'alpha1':int(np.sum((alpha==1)&~coverage)),'rgbaPreservedInFullPaddedAtlas':True};audit['generationProvenanceSha256']=sha(BASE/'generation-provenance.json');provenance=json.loads((BASE/'generation-provenance.json').read_text());record=next(r for r in provenance['results']if r['scope']==('full48'if N==48 else'style12'));assert record['rawSha256']==rawhash;assert any(r['path']==str(ref.relative_to(ROOT))and r['sha256']==sha(ref)for r in record['exactOrderedReferences']);audit['exactReferenceProvenanceVerified']=True
(O/'audit.json').write_text(json.dumps(audit,indent=2)+'\n')
