# Generic review player: same clock, one constant registration, no invented phases.
(O/"review.html").write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Рута — рисунок и 3D-позы</title>\n<style>body{font:16px system-ui;margin:0;background:#e9e4d9;color:#262721}header,footer{padding:10px 18px}h1{font-size:20px;margin:0 0 6px}p{margin:5px 0}button,input{font:inherit}button{padding:6px 12px}#controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}#frame{flex:1;min-width:160px;touch-action:pan-y}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:8px 16px}.card{text-align:center;border:1px solid #b9b3a8;border-radius:10px;background:#f5f0e6;padding:8px;overflow:hidden}h2{font-size:16px;margin:0 0 6px}canvas,#reference{display:block;height:min(52vh,480px);width:auto;max-width:100%;margin:auto;object-fit:contain;background-color:var(--scene,#ece2ce)}body[data-bg=dark]{--scene:#182028}body[data-bg=check]{--scene:#c9c9c9}body[data-bg=check] canvas{background-image:conic-gradient(#eee 25%,#ccc 0 50%,#eee 0 75%,#ccc 0);background-size:20px 20px}small{display:block;font-size:12px;line-height:1.3;margin-top:6px}#readout{font-variant-numeric:tabular-nums;min-width:180px}@media(max-width:600px){.cards{gap:4px;padding:4px}.card{padding:4px}h2{font-size:12px}header,footer{padding:7px}body{font-size:13px}}</style>\n<header><h1>Рута: рисованные кадры по 3D-позам</h1><p id="scope">Загрузка…</p><div id="controls"><button id="play" disabled>Пауза</button><input id="frame" type="range" min="0" max="47" value="0" step="1" disabled aria-label="Кадр"><span id="readout"></span><select id="background" aria-label="Фон"><option value="light">Светлый фон</option><option value="dark">Тёмный фон</option><option value="check">Шахматный фон</option></select></div></header>\n<main class="cards"><section class="card"><h2>Рисунок</h2><canvas id="painted" width="256" height="320"></canvas><small>Одна общая калибровка для всех кадров</small></section><section class="card"><h2>Исходные 3D-позы</h2><canvas id="native" width="256" height="320"></canvas><small>Та же фаза и длительность цикла</small></section><section class="card"><h2>Утверждённый эталон</h2><canvas id="reference" width="256" height="320" aria-label="Рута: утверждённый эталон внешности"></canvas></section></main>\n<footer><p id="calibration"></p><small>Пилот для сравнения. Общая калибровка — диагностическое сопоставление рисунка, не доказательство физической привязки стоп. Пиксели рисунка, включая слабую alpha, сохранены. Принятие рисунка и плавности — отдельно.</small><a href="manifest.json">Manifest</a> · <a href="audit.json">Аудит</a></footer>\n<script type="module">\nconst manifest=await(await fetch(\'manifest.json\')).json();\nconst load=async path=>{const im=new Image();im.src=path;await im.decode();return im};\nconst [paint,native,reference]=await Promise.all([load(manifest.paintedAtlas.path),load(manifest.nativeAtlas.path),load(manifest.reference.path)]);\nconst pc=document.querySelector(\'#painted\'),nc=document.querySelector(\'#native\');const [nw,nh]=manifest.nativeAtlas.frameSize;pc.width=nc.width=nw;pc.height=nc.height=nh;const pctx=pc.getContext(\'2d\'),nctx=nc.getContext(\'2d\');const rc=document.querySelector(\'#reference\');rc.width=nw;rc.height=nh;const rctx=rc.getContext(\'2d\'),referenceScale=manifest.nativeAtlas.nativeHeightPx/reference.height,[referenceAnchorX,referenceAnchorY]=manifest.nativeAtlas.footAnchor;const referenceDraw={scale:referenceScale,x:referenceAnchorX-reference.width*referenceScale/2,y:referenceAnchorY-reference.height*referenceScale,width:reference.width*referenceScale,height:reference.height*referenceScale};rctx.drawImage(reference,0,0,reference.width,reference.height,referenceDraw.x,referenceDraw.y,referenceDraw.width,referenceDraw.height);const play=document.querySelector(\'#play\'),slider=document.querySelector(\'#frame\');slider.max=manifest.frameCount-1;slider.disabled=play.disabled=false;\nconst fit=manifest.commonDiagnosticDisplayTransform,s=fit.paintedCellToNativeCanvasUniformScale,[tx,ty]=fit.translation;let epoch=performance.now();\nwindow.reviewState={ready:true,playing:true,frame:0,nativePhaseIndex:0,frameCount:manifest.frameCount,cycleSeconds:manifest.cycleSeconds,drawCount:0,commonScale:s,commonTranslation:[tx,ty],physicalRootCertified:false,referenceDraw};const state=window.reviewState;\ndocument.querySelector(\'#scope\').textContent=`${manifest.frameCount} поз · ${manifest.displayFramesPerSecond.toFixed(1)} кадра/с · цикл ${manifest.cycleSeconds.toFixed(6)} с${manifest.frameCount<48?\' — выбранные позы, не полный цикл48\':\'\'}`;\ndocument.querySelector(\'#calibration\').textContent=`Единый масштаб рисунка ${s.toFixed(6)}, сдвиг (${tx.toFixed(3)}, ${ty.toFixed(3)}). Индивидуальных сдвигов и масштабов нет.`;\nfunction draw(i){const row=manifest.frames[i],[x,y,w,h]=row.paintedRect,[a,b,c,d]=row.nativeRect;pctx.clearRect(0,0,nw,nh);nctx.clearRect(0,0,nw,nh);pctx.drawImage(paint,x,y,w,h,tx,ty,w*s,h*s);nctx.drawImage(native,a,b,c,d,0,0,nw,nh);state.frame=i;state.nativePhaseIndex=row.nativePhaseIndex;state.lastDraw={paintedRect:row.paintedRect,nativeRect:row.nativeRect,commonScale:s,commonTranslation:[tx,ty]};state.drawCount++;slider.value=i;document.querySelector(\'#readout\').textContent=`Кадр ${String(i).padStart(2,\'0\')} · 3D ${String(row.nativePhaseIndex).padStart(2,\'0\')}/48`;}\nfunction tick(now){if(state.playing){const elapsed=Math.max(0,now-epoch)/1000;const phase=(elapsed%manifest.cycleSeconds)/manifest.cycleSeconds;draw(Math.floor(phase*manifest.frameCount)%manifest.frameCount)}requestAnimationFrame(tick)}\nplay.onclick=()=>{state.playing=!state.playing;if(state.playing)epoch=performance.now()-state.frame/manifest.frameCount*manifest.cycleSeconds*1000;play.textContent=state.playing?\'Пауза\':\'Продолжить\'};\nslider.oninput=()=>{state.playing=false;play.textContent=\'Продолжить\';draw(Number(slider.value))};document.querySelector(\'#background\').onchange=e=>document.body.dataset.bg=e.target.value;draw(0);requestAnimationFrame(tick);\n</script></html>\n',encoding="utf-8")
